from collections import Counter, deque
def transform(g):
    h,w=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    seen=[[False]*w for _ in range(h)]; big=set()
    for i in range(h):
        for j in range(w):
            if not seen[i][j]:
                c=g[i][j]; q=deque([(i,j)]); seen[i][j]=True; n=0
                while q:
                    y,x=q.popleft(); n+=1
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and g[ny][nx]==c:
                            seen[ny][nx]=True; q.append((ny,nx))
                if n>=3: big.add(c)
    def get(i,j): return g[i][j] if 0<=i<h and 0<=j<w else None
    out=[r[:] for r in g]
    for i in range(h):
        for j in range(w):
            if g[i][j] in big: continue
            N={(dy,dx):get(i+dy,j+dx) for dy,dx in((1,0),(-1,0),(0,1),(0,-1))}
            cnt=Counter(v for v in N.values() if v is not None)
            if not cnt: continue
            top=max(cnt.values()); tied=[c for c,v in cnt.items() if v==top]
            pick=None
            if len(tied)==1: pick=tied[0]
            else:
                # L-corner: perpendicular adjacent pair of same color
                cand=[]
                for c in tied:
                    if ((N[(-1,0)]==c and N[(0,-1)]==c) or (N[(-1,0)]==c and N[(0,1)]==c) or
                        (N[(1,0)]==c and N[(0,-1)]==c) or (N[(1,0)]==c and N[(0,1)]==c)):
                        cand.append(c)
                bigc=[c for c in cand if c in big]
                if bigc: pick=bigc[0]
                elif cand: pick=[c for c in cand if c!=bg][0] if any(c!=bg for c in cand) else cand[0]
                else: pick=bg
            out[i][j]=pick
    return out
